import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
reach = [[False] * n for _ in range(n)]
for i in range(m):
    u = int(data[2 + 2 * i])
    v = int(data[3 + 2 * i])
    reach[u][v] = True
for k in range(n):
    for i in range(n):
        for j in range(n):
            if reach[i][k] and reach[k][j]:
                reach[i][j] = True
print('YES' if any(reach[i][i] for i in range(n)) else 'NO')

